# -*- coding: utf-8 -*-
# Нелин 11: сверка условий со сканом учебника (PDF, стр. 14–371) + самостоятельный пересчёт ключей (SymPy: check_nel1.py).
QG = "в условии была искажена запись (сверено со сканом учебника Нелин 11): "
KB = "ключ неверен (пересчитано вручную, сверено с ответом учебника Нелин 11): "
KF = "запись ключа была искажена (значение пересчитано): "
SRC = "самостоятельная проверка + скан учебника Нелин 11, 25.09"
P = {}
def E(t, why, **kw):
    P[t] = {"why": why, "src": SRC}; P[t].update(kw)
def D(v, w): return (v, w)
E("G11_TB_§3_5_4", QG + "функция y = (1 − 2x)/x² (§ 3, упр. 5 (4)); квадрат относился к знаменателю, а не ко всей дроби; ключ (2x − 2)/x³ верен для условия учебника",
  q=r"Найдите производную функции: $y=\dfrac{1-2x}{x^{2}}$")
E("G11_TB_§3_6_4", QG + "точка x = 0,1 была разорвана на «x = 0» и «1» (§ 3, упр. 6 (4)); ключ 1,5; 101 верен",
  q=r"Вычислите значения производной функции: $f(x)=x-\dfrac{1}{x}$ в точках: $x=-\sqrt{2}$, $x=0{,}1$")
E("G11_TB_§3_10_4", QG + "подкоренное выражение x² − 4, а не x³ − 4 (§ 3, упр. 10 (4), ответ учебника (−∞; −2) ∪ (2; +∞)); ключ пересчитан",
  q=r"Найдите область определения функции: $y = \dfrac{1}{\sqrt{x^{2} - 4}}$", k=r"$x \in (-\infty; -2) \cup (2; +\infty)$")
E("G11_TB_§4_2_3", QG + "функция та же, что в пунктах 2.1 и 2.2 — f(x) = √(x + 2)/x²; ключ (0; +∞) верен для неё (f′ = −x(3x + 8)/(2x⁴√(x + 2)))",
  q=r"Найдите значения $x$, при которых значение производной функции $f(x) = \dfrac{\sqrt{x+2}}{x^{2}}$ отрицательно.")
E("G11_TB_§4_11_4", QG + "функция f(x) = √x/(x + 2), а не √(x/(x + 2)) (§ 4, упр. 11 (4)); ключ x = 2 верен для условия учебника",
  q=r"Найдите значения: $x$, для которых производная функции $f(x)$ равна нулю: $f(x)=\dfrac{\sqrt{x}}{x+2}$")
E("G11_TB_§1_10", QG + "формула была разорвана лишними знаками $", qrep=(r"$f(x)=$x^{2}$+\sqrt[3]{x}$", r"$f(x)=x^{2}+\sqrt[3]{x}$"))
E("G11_TB_§8_1_1", KF + "ключ был записан как arcsin(x/(1 + x²)) + arctg(x/√(1 − x²)); (arcsin x·arctg x)′ = arctg x/√(1 − x²) + arcsin x/(1 + x²); вариант с этим же выражением закрыт",
  k=r"$\dfrac{\operatorname{arctg} x}{\sqrt{1-x^{2}}} + \dfrac{\arcsin x}{1+x^{2}}$", drop=[2])
E("G11_TB_§8_1_2", KF + "ключ был записан как −2·arcctg(x/(1 + x²)); (arcctg²x)′ = −2 arcctg x/(1 + x²)", k=r"$-\dfrac{2\operatorname{arcctg} x}{1+x^{2}}$")
E("G11_TB_§8_1_5", KF + "ключ был записан как cos(x/√(1 − sin²x)); (arcsin(sin x))′ = cos x/√(1 − sin²x)", k=r"$\dfrac{\cos x}{\sqrt{1-\sin^{2}x}}$")
E("G11_TB_§12_8", KB + "f′ = (3x² + (10 − 2a)x + 9)/(a − 2 − 3x − x²)² ≥ 0 при всех x ⇔ (10 − 2a)² ≤ 108 ⇔ 5 − 3√3 ≤ a ≤ 5 + 3√3 (было (−∞; −4] ∪ [2; +∞))",
  k=r"$a \in [5 - 3\sqrt{3}; 5 + 3\sqrt{3}]$")
E("G11_TB_§12_7", QG + "формула параболы была разорвана лишними знаками $", qrep=(r"$y = -$x^{2}$ + 4x + a$", r"$y = -x^{2} + 4x + a$"))
E("G11_TB_§12_Д2_2", KB + "знаменатель x³ − 2x + 4 = (x + 2)(x² − 2x + 2) обращается в нуль при x = −2, а числитель там равен −7 — вертикальная асимптота x = −2 (в ключе была только y = 1)",
  k=r"$x = -2$; $y = 1$")
E("G11_TB_§13_1_4", QG + "переменная z вместо x", q=r"Укажите, какие из данных функций возрастают, а какие убывают: $y=\pi^{x}$")
E("G11_TB_§13_6_10", QG + "число 0,2 было разорвано на «0» и «2»", q=r"Сравните значения выражений: $0{,}2^{-10}$ и $5^{11}$")
E("G11_TB_14_1_1_4", QG + "переменная λ вместо x", q=r"Решите уравнение: $7^{1-4x}=1$")
E("G11_TB_§15_5_6", QG + "показатель 1/2 относится к c в знаменателе (§ 15, упр. 5 (6)); вариант log₃(a^{2/5}) + log₃(b⁴) − log₃(c^{1/2}) равен ответу — закрыт",
  q=r"Прологарифмируйте данное выражение по заданному основанию, зная, что $a>0$, $b>0$, $c>0$: $\dfrac{a^{\frac{2}{5}}b^{4}}{c^{\frac{1}{2}}}$ по основанию $3$", drop=[2])
E("G11_TB_§15_6_3", QG + "в числителе c⁴, а не e⁴ (§ 15, упр. 6 (3), ответ учебника 4 lg|c| − …); ключ пересчитан; варианты с lg e заменены",
  q=r"Прологарифмируйте данное выражение по основанию $10$, зная, что $ab>0$ и $c\neq 0$: $\dfrac{c^{4}}{(ab)^{\frac{2}{5}}}$", k=r"$4\lg|c| - \dfrac{2}{5}\lg(ab)$",
  dnew={0: D(r"$4\lg c - \dfrac{2}{5}\lg(ab)$", "c может быть отрицательным — нужен модуль"), 1: D(r"$4\lg|c| + \dfrac{2}{5}\lg(ab)$", "неверный знак"), 2: D(r"$4\lg|c| - \dfrac{5}{2}\lg(ab)$", "перевёрнут показатель")})
E("G11_TB_§15_6_4", QG + "корень пятой степени, а не кубический (§ 15, упр. 6 (4)); ключ 2 + (1/5)lg(ab) + (2/5)lg|c| верен для условия учебника",
  q=r"Прологарифмируйте данное выражение по основанию $10$, зная, что $ab>0$ и $c\neq 0$: $100\sqrt[5]{abc^{2}}$")
E("G11_TB_§16_4_4", QG + "число 2,3 было разорвано на «2» и «3» (§ 16, упр. 4 (4))", q=r"Сравните числа: $\log_{\sqrt{3}}2{,}3$ и $\log_{\sqrt{3}}0{,}2$.")
E("G11_TB_17_2_4_1", QG + "потерян квадрат логарифма и основание: log²₃x − 3log₃x + 2 > 0 (§ 17, п. 17.2, упр. 4 (1)); ключ пересчитан, прежние варианты относились к искажённому условию",
  q=r"Решите неравенство: $\log_{3}^{2}x - 3\log_{3}x + 2 > 0$", k=r"$x \in (0; 3) \cup (9; +\infty)$",
  dnew={0: D(r"$x \in (3; 9)$", "перепутан знак неравенства"), 1: D(r"$x \in (0; 1) \cup (2; +\infty)$", "не выполнен обратный переход от log₃x к x"), 2: D(r"$x \in (9; +\infty)$", "потерян промежуток (0; 3)")})
E("G11_TB_17_2_4_3", QG + "потерян квадрат логарифма: log²_{1/3}x − 4 ≤ 0 (§ 17, п. 17.2, упр. 4 (3)); ключ пересчитан, прежние варианты относились к искажённому условию",
  q=r"Решите неравенство: $\log_{\frac{1}{3}}^{2}x - 4 \leq 0$", k=r"$x \in \left[\dfrac{1}{9}; 9\right]$",
  dnew={0: D(r"$x \in (0; 9]$", "потеряна нижняя граница"), 1: D(r"$x \in [-2; 2]$", "не выполнен обратный переход от log к x"), 2: D(r"$x \in \left(0; \dfrac{1}{9}\right] \cup [9; +\infty)$", "перепутан знак неравенства")})
E("G11_TB_17_2_4_4", QG + "потерян квадрат логарифма: log²_{1/2}x + log_{1/2}x − 2 ≥ 0 (§ 17, п. 17.2, упр. 4 (4), ответ учебника (0; 0,5] ∪ [4; +∞)); ключ пересчитан",
  q=r"Решите неравенство: $\log_{\frac{1}{2}}^{2}x + \log_{\frac{1}{2}}x - 2 \geq 0$", k=r"$x \in \left(0; \dfrac{1}{2}\right] \cup [4; +\infty)$",
  dnew={0: D(r"$x \in \left[\dfrac{1}{2}; 4\right]$", "перепутан знак неравенства"), 1: D(r"$0 < x \le \dfrac{1}{2}$", "потерян промежуток [4; +∞)"), 2: D(r"$x \in \left(0; \dfrac{1}{4}\right] \cup [2; +\infty)$", "не учтено убывание log₁/₂")})
E("G11_TB_§18_2_1", QG + "функция y = e^{5x} cos x (§ 18, упр. 2 (1)); «e^{āx}» — ошибка распознавания; ключ и варианты пересчитаны для e^{5x}",
  q=r"Найдите производную функции: $y = e^{5x} \cos x$.", k=r"$5e^{5x} \cos x - e^{5x} \sin x$",
  dnew={0: D(r"$5e^{5x} \cos x + e^{5x} \sin x$", "неверная производная cos x"), 1: D(r"$-5e^{5x} \sin x$", "перемножены производные множителей"), 2: D(r"$e^{5x} \cos x - 5e^{5x} \sin x$", "множитель 5 отнесён не к тому слагаемому")})
E("G11_TB_§18_4_1", QG + "формула была разорвана лишними знаками $", qrep=(r"$f(x)=$x^{2}$ \ln x$", r"$f(x)=x^{2} \ln x$"))
E("G11_TB_§18_4_2", QG + "формула была разорвана лишними знаками $", qrep=(r"$f(x)=$x^{3}$-3\ln x$", r"$f(x)=x^{3}-3\ln x$"))
E("G11_TB_25_1_1_4", QG + "верхний предел π/2, а не π/3 (§ 25, упр. 1 (4), ответ учебника 1); ключ пересчитан: −ctg x |_{π/4}^{π/2} = 1",
  q=r"Вычислите интеграл: $$\int_{\frac{\pi}{4}}^{\frac{\pi}{2}} \dfrac{dx}{\sin^{2} x}$$", k=r"$1$")
E("G11_TB_25_1_1_8", QG + "верхний предел π/2, а не π/3 (§ 25, упр. 1 (8), ответ учебника 0,5); ключ пересчитан: −cos 2x/2 |_{π/4}^{π/2} = 1/2",
  q=r"Вычислите интеграл: $$\int_{\frac{\pi}{4}}^{\frac{\pi}{2}} \sin 2x \, dx$$", k=r"$\dfrac{1}{2}$", dadd=[D(r"$\dfrac{1}{4}$", "значение для верхнего предела π/3")])
E("G11_TB_25_1_3_2", QG + "нижний предел −2, а не −π/2 (§ 25, упр. 3 (2), ответ учебника 2); ключ пересчитан: √(2x + 5) |_{−2}^{2} = 3 − 1 = 2; варианты с π заменены",
  q=r"Вычислите интеграл: $$\int_{-2}^{2} \dfrac{dx}{\sqrt{2x+5}}$$", k=r"$2$",
  dnew={0: D(r"$4$", "первообразная взята как 2√(2x + 5)"), 1: D(r"$3$", "не вычтено значение на нижнем пределе")})
E("G11_TB_25_1_3_4", QG + "нижний предел −2, а не −π/2 (§ 25, упр. 3 (4), ответ учебника 4); ключ пересчитан: 2√(x + 3) |_{−2}^{6} = 6 − 2 = 4; варианты с π заменены",
  q=r"Вычислите интеграл: $$\int_{-2}^{6} \dfrac{dx}{\sqrt{x+3}}$$", k=r"$4$",
  dnew={0: D(r"$2$", "первообразная взята как √(x + 3)"), 1: D(r"$6$", "не вычтено значение на нижнем пределе"), 2: D(r"$8$", "первообразная взята как 4√(x + 3)")})
E("G11_TB_25_1_3_6", QG + "верхний предел 2, а не 3/2 (§ 25, упр. 3 (6), ответ учебника 78); ключ пересчитан: (1 + 2x)⁴/8 |_{0}^{2} = (625 − 1)/8 = 78",
  q=r"Вычислите интеграл: $$\int_{0}^{2}(1+2x)^{3}dx$$", k=r"$78$",
  dnew={0: D(r"$\dfrac{255}{8}$", "значение для верхнего предела 3/2"), 1: D(r"$156$", "первообразная взята как (1 + 2x)⁴/4"), 2: D(r"$\dfrac{625}{8}$", "не вычтено значение на нижнем пределе")})
E("G11_TB_25_1_3_7", QG + "верхний предел π/12, а не π/3 (§ 25, упр. 3 (7)); ключ пересчитан: π/12 + sin(π/6)/2 = π/12 + 1/4",
  q=r"Вычислите интеграл: $$\int_{0}^{\frac{\pi}{12}}(1+\cos 2x)\,dx$$", k=r"$\dfrac{\pi}{12} + \dfrac{1}{4}$",
  dnew={0: D(r"$\dfrac{\pi}{12} + \dfrac{1}{2}$", "первообразная cos 2x взята как sin 2x"), 1: D(r"$\dfrac{\pi}{12} + \dfrac{\sqrt{3}}{4}$", "перепутаны sin и cos угла π/6"), 2: D(r"$\dfrac{\pi}{6} + \dfrac{1}{4}$", "неверно взята первообразная единицы")})
E("G11_TB_25_1_3_8", QG + "подынтегральная функция x + √x/x, а не x + √(x/x) (§ 25, упр. 3 (8), ответ учебника 9,5); ключ 19/2 верен для условия учебника",
  q=r"Вычислите интеграл: $$\int_{1}^{4} \left( x + \dfrac{\sqrt{x}}{x} \right) dx$$")
